using NovaHarvest.Core.Quests;
namespace NovaHarvest.Core.NPC.Characters; public static class LyraQuests { public static Quest FirstQuest() { var q = new Quest("quest_lyra_first_contact", "Uma Planta Familiar", "Lyra precisa de alguns recursos para recuperar sua pesquisa botânica e começar a estudar a flora alienígena do planeta.", "npc_lyra"); q.AddObjective(new QuestObjective("find_lumen_seeds", "Encontrar Lumen Seeds", 3)); q.AddObjective(new QuestObjective("find_green_crystal", "Encontrar um Cristal Verde", 1)); q.AddObjective(new QuestObjective("build_farm_plot", "Construir um canteiro", 1)); q.SetReward(new QuestReward(25, "alien_botany")); return q; } }
